def _load_vss_extension(self, conn: sqlite3.Connection) -> None:
    """Load the sqlite-vss extension on the given connection.

    Args:
        conn: SQLite connection to load the extension on.
    """
    conn.enable_load_extension(True)
    try:
        import sqlite_vss
        sqlite_vss.load(conn)
        logger.debug("vss0 extension loaded via sqlite_vss.load()")
    except Exception as e:
        # Fallback to manual loading
        logger.debug("sqlite_vss.load() failed, trying manual load: %s", e)
        package_dir = os.path.dirname(sqlite_vss.__file__)
        vector_path = os.path.join(package_dir, "vector0.so")
        vss_path = os.path.join(package_dir, "vss0.so")
        if os.path.exists(vector_path):
            conn.load_extension(vector_path)
            logger.debug("vector0 extension loaded manually")
        if os.path.exists(vss_path):
            conn.load_extension(vss_path)
            logger.debug("vss0 extension loaded manually")
        else:
            # Try vss_loadable_path
            vss_dir = sqlite_vss.vss_loadable_path()
            if os.path.isdir(vss_dir):
                vss_path = os.path.join(vss_dir, "vss0.so")
                vector_path = os.path.join(vss_dir, "vector0.so")
                if os.path.exists(vector_path):
                    conn.load_extension(vector_path)
                if os.path.exists(vss_path):
                    conn.load_extension(vss_path)
                logger.debug("vss0 extension loaded from vss_loadable_path")
            else:
                logger.warning("Could not find vss0.so or vss0 directory")
    except ImportError:
        logger.warning("sqlite_vss module not available")
        raise RuntimeError("sqlite-vss is a HARD REQUIREMENT but is not available.")

